test.describe("cookie consent tests", () => {
  test.beforeEach(async ({ page }) => {
    await page.goto("/");
  });

  test("cookie consent banner rejection does not set cc_cookie", async ({
    context,
    page,
  }) => {
    await page.$$('button:has-text("Reject all")');
    await page.click('button:has-text("Reject all")');

    const cookies = await context.cookies();
    const consentCookie = cookies.find((c) => c.name === "cc_cookie");
    const cookieObject = JSON.parse(decodeURIComponent(consentCookie.value));
    expect(cookieObject.categories.includes("analytics")).toBeFalsy();
  });

  test("cookie consent banner acceptance sets cc_cookie and _ga cookies", async ({
    context,
    page,
  }) => {
    await page.$$('button:has-text("Accept all")');
    await page.click('button:has-text("Accept all")');

    let cookies = await context.cookies();
    const consentCookie = cookies.find((c) => c.name === "cc_cookie");
    const cookieObject = JSON.parse(decodeURIComponent(consentCookie.value));
    // Check that the Cookie Consent cookie is set. This should happen immediately, and then the GA cookies will get set after it, dynamically.
    expect(cookieObject.categories.includes("analytics")).toBeTruthy();

    const areGaCookiesSet = (cookies: Cookie[]) => {
      const gaCookiesArr = cookies.filter((c) => c.name.startsWith("_ga"));
      return gaCookiesArr.length === 2; // GA cookies are _ga and _ga_<GA_ANALYTICS_ID>
    };

    const startTime = Date.now();
    const MAX_TIME_MS = 10000;
    let timeElapsed = 0;

    while (!areGaCookiesSet(cookies) && timeElapsed < MAX_TIME_MS) {
      await new Promise((resolve) => setTimeout(resolve, 1000)); // wait for 1 second before checking again
      cookies = await context.cookies();
      timeElapsed = Date.now() - startTime;
    }

    expect(timeElapsed).toBeLessThan(MAX_TIME_MS);
  });
});

import { expect, test, type Page } from "@playwright/test";
import {
  acceptAllCookies,
  createRandomUser,
  logUserIn,
  makeStripePayment,
  signUserUp,
  type User,
} from "./utils";

let page: Page;
let testUser: User;

async function createAndLogInNewUser() {
  testUser = createRandomUser();
  await signUserUp({ page: page, user: testUser });
  await logUserIn({ page: page, user: testUser });
}

// We need to run the tests sequentially to check for functionality before and after the user pays.
test.describe.configure({ mode: "serial" });

test.beforeAll(async ({ browser }) => {
  page = await browser.newPage();
});

test.afterAll(async () => {
  await page.close();
});

test("User should see Log In to Buy Plan button", async () => {
  await page.goto("/pricing");
  // There are three tiers on the page, so we want to retrieve the first of the three buttons
  const buyPlanButton = page
    .getByRole("button", { name: "Log in to buy plan" })
    .first();
  await expect(buyPlanButton).toBeVisible();
  await expect(buyPlanButton).toBeEnabled();
  await buyPlanButton.click();
  await page.waitForURL("**/login");
  expect(page.url()).toContain("/login");
});

test("User should see the Buy Plan button before payment", async () => {
  // We only need to log the user in once since the tests are running sequentially
  // and the same page is being shared between all the tests.
  await createAndLogInNewUser();
  await page.goto("/pricing");
  // There are three tiers on the page, so we want to retrieve the first of the three buttons
  const manageSubscriptionButton = page
    .getByRole("button", { name: "Buy plan" })
    .first();
  await expect(manageSubscriptionButton).toBeVisible();
  await expect(manageSubscriptionButton).toBeEnabled();
});

test("Make test payment with Stripe for hobby plan", async () => {
  const planId = "hobby";
  await page.goto("/");
  await makeStripePayment({ test, page, planId });
});

test("User should see the Manage Subscription button after payment", async () => {
  await page.goto("/pricing");
  // There are three tiers on the page, so we want to retrieve the first of the three buttons
  const manageSubscriptionButton = page
    .getByRole("button", { name: "Manage Subscription" })
    .first();
  await expect(manageSubscriptionButton).toBeVisible();
  await expect(manageSubscriptionButton).toBeEnabled();
  await manageSubscriptionButton.click();
  // clicking the button should take the user to the Stripe customer portal page with substring 'billing.stripe.com' in a new window
  const newTabPromise = page.waitForEvent("popup");
  const newTab = await newTabPromise;
  await newTab.waitForLoadState();
  await expect(newTab).toHaveURL(/^https:\/\/billing\.stripe\.com\//);
});

test("Make test payment with Stripe for 10 credits", async () => {
  await createAndLogInNewUser();
  await acceptAllCookies(page); // Clear the cookie consent modal so it doesn't interfere with the payment
  const planId = "credits10";
  await page.goto("/");
  await makeStripePayment({ test, page, planId });
});

# AGENTS.md

This document provides guidelines for agentic coding assistants working in this repository.

## Development Commands

```bash
# Build
pnpm build           # Production build (typecheck + minify)
pnpm build:dev       # Development build (no minification)
pnpm watch           # Watch mode for iterative development

# Testing
pnpm test            # Run all tests once
pnpm test:dev        # Run tests in watch mode
npx vitest run <test-file>     # Run single test file
pnpm run test -- <pattern>     # Run tests matching pattern

# Linting & Formatting
pnpm lint            # Typecheck + ESLint
pnpm format          # Format code with Prettier

# Run CLI
pnpm start           # Run built CLI
node dist/index.mjs  # Alternative run command
```

## Code Style

### Formatting

- **Prettier**: 80 char width, single quotes, 2 spaces, semicolons required
- **No comments**: Do not add comments unless explicitly requested
- **Section dividers**: Use `// ======` lines for major code sections

### Imports

```typescript
// Group imports in this order:
import fs from 'node:fs/promises'; // Node.js built-ins (use node: prefix)
import path from 'node:path';
import chalk from 'chalk'; // Third-party libraries
import ink from 'ink';
import { getConfig } from '@/config'; // Internal imports (use @/ alias)
import { PatchConfig } from '@/types';
```

### TypeScript

- **Strict mode** enabled in tsconfig.json
- **Avoid `any`**: Use `unknown` with type guards or `as unknown as Type` for assertions
- **Interfaces** for complex objects, types for simple unions
- **Custom errors**: Extend `Error` class with `name` property

```typescript
export class CustomError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'CustomError';
  }
}
```

### Naming Conventions

- **Files**: camelCase for logic (`config.ts`), PascalCase for React components (`MainView.tsx`)
- **Functions**: camelCase (`getConfig`, `detectInstallation`)
- **Constants**: UPPER_SNAKE_CASE (`CONFIG_DIR`, `DEFAULT_CONFIG`)
- **Components**: PascalCase with descriptive names (`ThinkingVerbsView`)
- **Interfaces**: PascalCase, descriptive (`StringsPrompt`, `MarkdownPrompt`)

### Error Handling

```typescript
try {
  const result = await someAsyncOperation();
  return result;
} catch (error) {
  debug('Error occurred:', error);
  return null; // Graceful fallback
}
```

### React Patterns

- Use hooks: `useState`, `useEffect`, `useCallback`
- Context API for state management
- Ink components: `Box`, `Text`, `Newline`
- Explicit prop types with interfaces

### Writing Patches

- **Identifier matching**: Use `[$\\w]+` instead of `\\w+` (includes `$` for React refs)
- **Word boundaries**: Use `,` `;` `}` `{` literal characters at regex start instead of `\\b` for performance
- **Avoid `\\b`**: Performance issue in V8, use literal alternatives

### Testing

```typescript
// Use Vitest globals
import { describe, it, expect, beforeEach, vi } from 'vitest';

describe('functionName', () => {
  beforeEach(() => {
    vi.mock('some-module');
  });

  it('should do something', () => {
    expect(result).toBe(expected);
  });
});
```

- Test files in `src/tests/*.test.ts` and `src/patches/*.test.ts`
- Mock dependencies with `vi.mock()`
- Test edge cases and error conditions

### CLI Patterns

- Use `ink` for CLI rendering
- Use `chalk` for terminal colors
- Use `commander` for CLI argument parsing
- Add shebang to index.tsx for executable support

import { describe, it, expect } from 'vitest';
import { writeAgentsMd } from './agentsMd';

const mockFunction =
  'function _t7(A,q){try{let K=x1();' +
  'if(!K.existsSync(A)||!K.statSync(A).isFile())return null;' +
  'let Y=UL9(A).toLowerCase();' +
  'if(Y&&!dL9.has(Y))' +
  'return(I(`Skipping non-text file in @include: ${A}`),null);' +
  'let z=K.readFileSync(A,{encoding:"utf-8"}),' +
  '{content:w,paths:H}=cL9(z);' +
  'return{path:A,type:q,content:w,globs:H};' +
  '}catch(K){' +
  'if(K instanceof Error&&K.message.includes("EACCES"))' +
  'n("tengu_claude_md_permission_error",{is_access_error:1});' +
  '}return null;}';

const altNames = ['AGENTS.md', 'GEMINI.md', 'QWEN.md'];

describe('agentsMd', () => {
  describe('writeAgentsMd', () => {
    it('should inject fallback at early return null when CLAUDE.md is missing', () => {
      const result = writeAgentsMd(mockFunction, altNames);
      expect(result).not.toBeNull();
      expect(result).toContain('didReroute');
      expect(result).toContain('endsWith("/CLAUDE.md")');
      expect(result).toContain('AGENTS.md');
      expect(result).toMatch(/\.isFile\(\)\)\{.*?return null;\}/);
    });

    it('should preserve CLAUDE.md content when present', () => {
      const result = writeAgentsMd(mockFunction, altNames)!;
      const returnIdx = result.indexOf('return{path:');
      expect(returnIdx).toBeGreaterThan(-1);
      const beforeReturn = result.slice(Math.max(0, returnIdx - 50), returnIdx);
      expect(beforeReturn).not.toContain('didReroute');
    });

    it('should pass didReroute=true in recursive calls', () => {
      const result = writeAgentsMd(mockFunction, altNames)!;
      expect(result).toContain('return _t7(altPath,q,true)');
    });

    it('should return null when no alternatives are found', () => {
      const result = writeAgentsMd(mockFunction, altNames)!;
      expect(result).toMatch(/\}return null;\}/);
    });

    it('should add didReroute parameter to function signature', () => {
      const result = writeAgentsMd(mockFunction, altNames)!;
      expect(result).toContain('function _t7(A,q,didReroute)');
    });

    it('should use the correct fs expression', () => {
      const result = writeAgentsMd(mockFunction, altNames)!;
      expect(result).toContain('K.existsSync(altPath)');
      expect(result).toContain('K.statSync(altPath)');
    });

    it('should return null when function pattern is not found', () => {
      const result = writeAgentsMd('not a valid file', altNames);
      expect(result).toBeNull();
    });
  });
});

import { describe, it, expect } from 'vitest';
import { writeAllowCustomAgentModels } from './allowCustomAgentModels';

// CC 2.1.69 style - realistic mock based on actual extracted JS
// Patch 1 target: ,model:u.enum(oEH).optional()
// Patch 2 target: ");let J=K&&typeof K==="string"&&oEH.includes(K)
const mockContent69 =
  'prompt:u.string().min(1,"Prompt cannot be empty"),' +
  'model:u.enum(oEH).optional(),' +
  'effort:u.union([u.enum($OH),u.number().int()]).optional()' +
  "console.warn(`Agent file ${H} has invalid isolation value '${Y}'. " +
  'Valid options: ${z.join(", ")}`);' +
  'let J=K&&typeof K==="string"&&oEH.includes(K);' +
  'if(K&&typeof K==="string"&&!J){' +
  'let $H=`Agent file ${H} has invalid model`}' +
  'return{...obj,...J?{model:K}:{}}';

// CC 2.1.70 style - different minified variable names
const mockContent70 =
  'prompt:u.string().min(1,"Prompt cannot be empty"),' +
  'model:u.enum(yjH).optional(),' +
  'effort:u.union([u.enum(WOH),u.number().int()]).optional()' +
  "console.warn(`Agent file ${H} has invalid isolation value '${Y}'. " +
  'Valid options: ${z.join(", ")}`);' +
  'let X=K&&typeof K==="string"&&yjH.includes(K);' +
  'if(K&&typeof K==="string"&&!X){' +
  'let s=`Agent file ${H} has invalid model`}' +
  'return{...obj,...X?{model:K}:{}}';

// Mock with } boundary (original patch expected this)
const mockContentBraces =
  'let A=x1();' +
  '{description:M,color:K,model:x.enum(hWH).optional(),' +
  'background:x.string().optional()}' +
  'let E=A.model;' +
  '}let _=E&&typeof E==="string"&&hWH.includes(E);' +
  'return{...obj,..._?{model:E}:{}}';

// FALSE POSITIVE SCENARIO: a structurally similar pattern using a DIFFERENT
// array variable appears BEFORE the real model validation pattern.
// With the unfixed regex, String.match() would grab the first match
// (otherArr), missing the real target (oEH).
const mockWithFalsePositiveBefore =
  'someSetup();' +
  ';let $c=F&&typeof F==="string"&&otherArr.includes(F);' +
  'someMoreCode();' +
  'prompt:u.string().min(1,"Prompt cannot be empty"),' +
  'model:u.enum(oEH).optional(),' +
  'effort:u.union([u.enum($OH),u.number().int()]).optional()' +
  'console.warn(`done`);' +
  'let J=K&&typeof K==="string"&&oEH.includes(K);' +
  'return{...obj,...J?{model:K}:{}}';

// Only Zod pattern, validation missing
const mockOnlyZod =
  'prompt:u.string(),' +
  'model:u.enum(oEH).optional(),' +
  'effort:u.string().optional()';

// Only validation pattern, Zod missing
const mockOnlyValidation =
  'let E=A.model;' +
  ';let _=E&&typeof E==="string"&&oEH.includes(E);' +
  'return{...obj,..._?{model:E}:{}}';

describe('allowCustomAgentModels', () => {
  describe('writeAllowCustomAgentModels', () => {
    it('should replace Zod enum with string (CC 2.1.69)', () => {
      const result = writeAllowCustomAgentModels(mockContent69);
      expect(result).not.toBeNull();
      expect(result).toContain('model:u.string().optional()');
      expect(result).not.toContain('enum(oEH)');
    });

    it('should remove includes check from validation flag (CC 2.1.69)', () => {
      const result = writeAllowCustomAgentModels(mockContent69);
      expect(result).not.toBeNull();
      expect(result).toContain(';let J=K&&typeof K==="string"');
      expect(result).not.toContain('oEH.includes(K)');
    });

    it('should preserve the ternary model injection', () => {
      const result = writeAllowCustomAgentModels(mockContent69)!;
      expect(result).toContain('J?{model:K}:{}');
    });

    it('should work with CC 2.1.70 variable names', () => {
      const result = writeAllowCustomAgentModels(mockContent70);
      expect(result).not.toBeNull();
      expect(result).toContain('model:u.string().optional()');
      expect(result).not.toContain('enum(yjH)');
      expect(result).not.toContain('yjH.includes(K)');
    });

    it('should handle } boundary character before let', () => {
      const result = writeAllowCustomAgentModels(mockContentBraces);
      expect(result).not.toBeNull();
      expect(result).toContain('}let _=E&&typeof E==="string"');
      expect(result).not.toContain('hWH.includes(E)');
    });

    it('should return null when no patterns found', () => {
      const result = writeAllowCustomAgentModels(
        'totally unrelated code with no patterns'
      );
      expect(result).toBeNull();
    });

    it('should return null when only Zod pattern found', () => {
      const result = writeAllowCustomAgentModels(mockOnlyZod);
      expect(result).toBeNull();
    });

    it('should return null when only validation pattern found', () => {
      const result = writeAllowCustomAgentModels(mockOnlyValidation);
      expect(result).toBeNull();
    });

    it('should not match a false positive with different array variable', () => {
      const result = writeAllowCustomAgentModels(mockWithFalsePositiveBefore);
      expect(result).not.toBeNull();
      // The otherArr pattern must be left untouched
      expect(result).toContain('otherArr.includes(F)');
      // The real oEH pattern must be modified
      expect(result).not.toContain('oEH.includes(K)');
      // Zod pattern must also be modified
      expect(result).toContain('model:u.string().optional()');
    });
  });
});

