  expect(isBinaryFile("/path/to/.DS_Store")).toBe(true);
  expect(isBinaryFile("some/dir/.DS_Store")).toBe(true);
});

test("isBinaryFile returns false for text extensions", () => {
  expect(isBinaryFile("readme.md")).toBe(false);
