from pathlib import Path
import sys
import os

def find_directories(project_dir, target_dirs):
    """Find directories using multiple search strategies."""
    project_dir = Path(project_dir).resolve()
    print(f"Looking for directories in: {project_dir}")
    print(f"Target directories: {target_dirs}")

    found_dirs = []

    # Strategy 1: Direct lookup at the top level
    print("\nStrategy 1: Direct top-level lookup")
    for target in target_dirs:
        path = project_dir / target
        if path.exists() and path.is_dir():
            print(f"✅ Found at top level: {path}")
            found_dirs.append(path)
        else:
            print(f"❌ Not found at top level: {target}")

    # Strategy 2: Search one level down
    print("\nStrategy 2: One level down search")
    for item in project_dir.iterdir():
        if item.is_dir() and not item.name.startswith('.'):
            for target in target_dirs:
                path = item / target
                if path.exists() and path.is_dir():
                    print(f"✅ Found one level down: {path}")
                    found_dirs.append(path)

    # Strategy 3: Case-insensitive search
    print("\nStrategy 3: Case-insensitive search")
    for target in target_dirs:
        target_lower = target.lower()
        for item in project_dir.rglob("*"):
            if item.is_dir() and item.name.lower() == target_lower:
                print(f"✅ Found with case-insensitive search: {item}")
                found_dirs.append(item)

    # Strategy 4: Partial name match
    print("\nStrategy 4: Partial name match")
    for target in target_dirs:
        for item in project_dir.rglob("*"):
            if item.is_dir() and target.lower() in item.name.lower():
                print(f"✅ Found with partial name match: {item}")
                found_dirs.append(item)

    print(f"\nTotal found directories: {len(set(found_dirs))}")
    for dir_path in sorted(set(found_dirs)):
        print(f"  - {dir_path}")

    return found_dirs

if __name__ == "__main__":
    # Get target directory and focus dirs from command line
    project_dir = sys.argv[1] if len(sys.argv) > 1 else "../cursor-chat-browser"
    target_dirs = sys.argv[2:] if len(sys.argv) > 2 else ["api", "app", "src"]

    find_directories(project_dir, target_dirs)

name: Check Plugin Structure

on:
  pull_request:
    branches: [staged]
    paths:
      - "plugins/**"

permissions:
  contents: read
  pull-requests: write

jobs:
  check-materialized-files:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout
        uses: actions/checkout@v4

      - name: Check for materialized files in plugin directories
        uses: actions/github-script@v7
        with:
          script: |
            const { execSync } = require('child_process');
            const fs = require('fs');
            const path = require('path');

            const pluginsDir = 'plugins';
            const errors = [];

            if (!fs.existsSync(pluginsDir)) {
              console.log('No plugins directory found');
              return;
            }

            const pluginDirs = fs.readdirSync(pluginsDir, { withFileTypes: true })
              .filter(d => d.isDirectory())
              .map(d => d.name);

            for (const plugin of pluginDirs) {
              const pluginPath = path.join(pluginsDir, plugin);

              // Check for materialized agent/command/skill files
              for (const subdir of ['agents', 'commands', 'skills']) {
                const subdirPath = path.join(pluginPath, subdir);
                if (!fs.existsSync(subdirPath)) continue;

                const stat = fs.lstatSync(subdirPath);
                if (stat.isSymbolicLink()) {
                  errors.push(`${pluginPath}/${subdir} is a symlink — symlinks should not exist in plugin directories`);
                  continue;
                }

                if (stat.isDirectory()) {
                  const files = fs.readdirSync(subdirPath);
                  if (files.length > 0) {
                    errors.push(
                      `${pluginPath}/${subdir}/ contains ${files.length} file(s): ${files.join(', ')}. ` +
                      `Plugin directories on staged should only contain .github/plugin/plugin.json and README.md. ` +
                      `Agent, command, and skill files are materialized automatically during publish to main.`
                    );
                  }
                }
              }

              // Check for symlinks anywhere in the plugin directory
              try {
                const allFiles = execSync(`find "${pluginPath}" -type l`, { encoding: 'utf-8' }).trim();
                if (allFiles) {
                  errors.push(`${pluginPath} contains symlinks:\n${allFiles}`);
                }
              } catch (e) {
                // find returns non-zero if no matches, ignore
              }
            }

            if (errors.length > 0) {
              const prBranch = context.payload.pull_request.head.ref;
              const prRepo = context.payload.pull_request.head.repo.full_name;
              const isFork = context.payload.pull_request.head.repo.fork;

              const body = [
                '⚠️ **Materialized files or symlinks detected in plugin directories**',
                '',
                'Plugin directories on the `staged` branch should only contain:',
                '- `.github/plugin/plugin.json` (metadata)',
                '- `README.md`',
                '',
                'Agent, command, and skill files are copied in automatically when publishing to `main`.',
                '',
                '**Issues found:**',
                ...errors.map(e => `- ${e}`),
                '',
                '---',
                '',
                '### How to fix',
                '',
                'It looks like your branch may be based on `main` (which contains materialized files). Here are two options:',
                '',
                '**Option 1: Rebase onto `staged`** (recommended if you have few commits)',
                '```bash',
                `git fetch origin staged`,
                `git rebase --onto origin/staged origin/main ${prBranch}`,
                `git push --force-with-lease`,
                '```',
                '',
                '**Option 2: Remove the extra files manually**',
                '```bash',
                '# Remove materialized files from plugin directories',
                'find plugins/ -mindepth 2 -maxdepth 2 -type d \\( -name agents -o -name commands -o -name skills \\) -exec rm -rf {} +',
                '# Remove any symlinks',
                'find plugins/ -type l -delete',
                'git add -A && git commit -m "fix: remove materialized plugin files"',
                'git push',
                '```',
              ].join('\n');

              await github.rest.pulls.createReview({
                owner: context.repo.owner,
                repo: context.repo.repo,
                pull_number: context.issue.number,
                event: 'REQUEST_CHANGES',
                body
              });

              core.setFailed('Plugin directories contain materialized files or symlinks that should not be on staged');
            } else {
              console.log('✅ All plugin directories are clean');
            }

name: Link Language Check

on:
  workflow_call:
    inputs:
      soft-fail:
        description: 'Whether to continue on language path violations'
        required: false
        type: boolean
        default: false

permissions:
  contents: read

jobs:
  link-lang-check:
    name: Check for Language Paths in URLs
    runs-on: ubuntu-latest
    permissions:
      contents: read
    steps:
      - name: Checkout code
        uses: actions/checkout@de0fac2e4500dabe0009e67214ff5f5447ce83dd # v4.2.2
        with:
          persist-credentials: false

      - name: Create logs directory
        shell: pwsh
        run: |
          New-Item -ItemType Directory -Force -Path logs | Out-Null

      - name: Run Link Language Check
        shell: pwsh
        run: |
          & scripts/linting/Invoke-LinkLanguageCheck.ps1 -ExcludePaths 'scripts/tests/**'
        continue-on-error: true

      - name: Upload results
        if: always()
        uses: actions/upload-artifact@bbbca2ddaa5d8feaa63e36b76fdaad77386f024f # v4.4.3
        with:
          name: link-lang-check-results
          path: logs/link-lang-check-results.json
          retention-days: 30

      - name: Check results and fail if needed
        if: ${{ !inputs.soft-fail }}
        shell: pwsh
        run: |
          if ($env:LINK_LANG_FAILED -eq 'true') {
            $resultsPath = 'logs/link-lang-check-results.json'

            if (Test-Path -LiteralPath $resultsPath) {
              try {
                $results = Get-Content -LiteralPath $resultsPath -Raw | ConvertFrom-Json
                $totalIssues = [int]($results.summary.total_issues)
                $filesAffected = [int]($results.summary.files_affected)

                if ($results.issues -and $results.issues.Count -gt 0) {
                  if ($totalIssues -le 0) {
                    $totalIssues = [int]$results.issues.Count
                  }

                  if ($filesAffected -le 0) {
                    $filesAffected = [int](($results.issues | Select-Object -ExpandProperty file -Unique).Count)
                  }

                  Write-Host "❌ Link language check failed with $totalIssues issue(s) in $filesAffected file(s)."

                  foreach ($issue in $results.issues) {
                    Write-Host "  ⚠️ $($issue.file):$($issue.line_number) - $($issue.original_url)"
                  }
                } else {
                  Write-Host 'Link language check failed and no issue entries were found in logs/link-lang-check-results.json.'
                }
              } catch {
                Write-Host 'Link language check failed and logs/link-lang-check-results.json could not be parsed.'
              }
            } else {
              Write-Host 'Link language check failed and logs/link-lang-check-results.json was not found.'
            }

            exit 1
          }

